package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	num() // n: every following number is an array element
	// last[mask]: smallest final value of an increasing subsequence whose OR is mask (1024 = unreachable).
	last := make([]int64, 1024)
	for i := range last {
		last[i] = 1024
	}
	last[0] = 0 // empty subsequence
	for skipSpace() {
		v := num()
		for mask := int64(0); mask < 1024; mask++ {
			if last[mask] < v {
				last[mask|v] = min(last[mask|v], v)
			}
		}
	}
	values := []byte{}
	count := 0
	for i := range last {
		if last[i] < 1024 {
			if count > 0 {
				values = append(values, ' ')
			}
			count++
			values = strconv.AppendInt(values, int64(i), 10)
		}
	}
	out := strconv.AppendInt(nil, int64(count), 10)
	out = append(out, '\n')
	out = append(out, values...)
	out = append(out, '\n')
	os.Stdout.Write(out)
}
